          .. " goal_card_state=" .. tostring(goal_state)
          .. " goal_card_object_slot=" .. tostring(goal_slot)
          .. " form_before_clear=" .. tostring(world_8_2_clear_state.form)
          .. " cards_before_touch=" .. tostring(world_8_2_clear_state.cards_before[1])
