                        - math.abs(H_m.x - 540) * 2
                      local H_child_checkpoint = savestate.create()
                      savestate.save(H_child_checkpoint)
                      H_candidates[#H_candidates + 1] = {
                        checkpoint = H_child_checkpoint,
                        sequence = H_sequence,
                        score = H_score,
                        x = H_m.x,
                        y = H_m.y,
                        air = H_m.air,
                        form = memory.readbyte(0xED),
                      }
                    end
