            held.left = direct_m.x > 552
            held.right = direct_m.x < 544
            held.A = direct_inside_frames >= 90
              and direct_inside_frames % 54 < 34
            held.up = direct_m.x >= 538 and direct_m.x <= 558
              and direct_m.air == 0
          elseif direct_top_phase == 1 then
