if discovery_resume_slot ~= nil then
  local discovery_resume_phase = os.getenv("SMB3_DISCOVERY_RESUME_PHASE")
  local discovery_resume_settle_frames =
    (discovery_resume_phase == "post_g_lava"
      or discovery_resume_phase == "post_g_late") and 1 or 10
  advance(discovery_resume_settle_frames, "post_probe_world_8_discovery_resume")
  if world_8_extension_mode == "world_8_finish_game_discovery" then
    run_world_8_bowser_castle_finish_extension(true)
  else
    run_world_8_fortress_super_tanks_extension(true)
  end
  log:close()
  emu.exit()
  return
end

local embedded_takeover = rawget(_G, "SMB3_EMBEDDED_TAKEOVER") == true
local embedded_policy = rawget(_G, "SMB3_EMBEDDED_TAKEOVER_POLICY")
if embedded_takeover and (embedded_policy == "world_1_1_remainder_v1"
    or embedded_policy == "b2_world_1_1_plan_v1") then
  bootstrap_to_level = function() end
end
bootstrap_to_level()
if attempts == 1 then
  -- A single-attempt acceptance replay runs straight from the power-on boot.
  -- Checkpoints remain available only for explicitly requested retry batches.
  advance(10, "attempt_1_fresh_start")
  local success = run_agent(1)
  local b2_plan = rawget(_G, "SMB3_B2_PLAN")
  if b2_plan and not success then error("GAME_COMPANION_B2_CONTROLLER_INCOMPLETE") end
  if b2_plan and success then b2_plan.boundary("world_1_1_exit") end
  if success and not (embedded_takeover and embedded_policy == "world_1_1_remainder_v1") then
    run_post_1_1_probe()
  end
else
  local checkpoint = savestate.create()
  savestate.save(checkpoint)
  for attempt = 1, attempts do
    savestate.load(checkpoint)
    advance(10, "attempt_" .. tostring(attempt) .. "_start")
    local success = run_agent(attempt)
    if attempt == attempts and success then
      run_post_1_1_probe()
    end
  end
end

log:close()
if embedded_takeover then
  return
end
emu.exit()
